package org.marketreview.nativeapp;
import org.json.*;
import java.util.*;
import java.time.*;
import java.util.function.BooleanSupplier;
final class CandidateThemeSelection {
 static final String SCHEMA="native-candidate-theme-selection/v1";
 static final String BOUNDARY="明确选择的本机主题/资料关系；匹配不代表全市场主题归属或事实核验。只证明当前观察，发布时点及当时可获得性未证实。未选择的资料不参与；主营、估值、AI不参与评分。";
 static void need(boolean b,String s){if(!b)throw new IllegalArgumentException(s);}
 static void active(BooleanSupplier c)throws Exception{SectorLeaderModel.active(c);}
 static Map<String,JSONObject> index(JSONArray a)throws Exception{need(a!=null&&a.length()<=10000,"来源缺失或超过10000条");Map<String,JSONObject> m=new TreeMap<>();for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);String id=r.optString("id");need(!id.trim().isEmpty()&&id.length()<=128&&!m.containsKey(id),"来源ID缺失、超长或重复");m.put(id,r);}return m;}
 static JSONObject select(JSONObject cat,JSONArray securities,List<String> topicIds,List<String> relationIds,String text,BooleanSupplier c)throws Exception{
  active(c);need(text.length()<=512&&topicIds.size()<=20&&relationIds.size()<=100&&securities.length()>0&&securities.length()<=50,"需求/主题/资料关系/证券超过范围");Map<String,JSONObject> ts=index(cat.getJSONArray("topics")),rs=index(cat.getJSONArray("relations")),ds=index(cat.getJSONArray("docs")),ss=index(securities);Map<String,String> texts=new HashMap<>();for(String id:ds.keySet())texts.put(id,ds.get(id).getString("text"));
  JSONArray ids=new JSONArray(),topics=new JSONArray(),relations=new JSONArray(),documents=new JSONArray(),members=new JSONArray(),demandIds=new JSONArray();Set<String> tids=new HashSet<>(),rids=new HashSet<>(),dids=new TreeSet<>();
  for(String id:ss.keySet()){need(ResearchCompanies.identity(id)&&!ss.get(id).has("backgroundInput"),"证券须明确市场，且使用未附加背景的完整输入");ids.put(id);}
  for(String id:topicIds){active(c);need(ts.containsKey(id)&&tids.add(id),"需求主题已缺失或重复");JSONObject t=ts.get(id);need(t.opt("name") instanceof String&&!t.getString("name").trim().isEmpty()&&t.getString("name").length()<=120,"主题名称无效");topics.put(t);demandIds.put(id);}
  for(String id:relationIds){active(c);need(rs.containsKey(id)&&rids.add(id),"成员关系已缺失或重复");JSONObject r=rs.get(id),company=r.getJSONObject("company");String security=company.optString("instrumentId"),topic=r.optString("topicId");need(ss.containsKey(security)&&tids.contains(topic),"成员须绑定本次完整证券与需求主题");ResearchCompanies.validateReferences(r,texts);String doc=r.optString("documentId");need(ds.containsKey(doc)&&r.opt("quote") instanceof String&&!r.getString("quote").trim().isEmpty()&&texts.get(doc).contains(r.getString("quote")),"成员引文与完整原文不匹配");need(r.optString("polarity").equals("supports"),"反证不能作为正向主题成员");relations.put(r);dids.add(doc);dids.add(company.getString("identityDocumentId"));members.put(new JSONObject().put("id",id).put("securityId",security).put("themeId",topic).put("name",ts.get(topic).get("name")).put("kind","reference").put("relationHash",LocalCandidateBackgroundAdapter.sourceDigest(r)).put("verification",r.optString("verification","unverified")));}
  for(String id:dids){active(c);need(ds.containsKey(id),"身份资料缺失");documents.put(ds.get(id));}
  JSONObject versions=new JSONObject();String[] keys={"securities","topics","relations","docs"};JSONArray[] arrays={securities,topics,relations,documents};for(int i=0;i<keys.length;i++){JSONObject hashes=new JSONObject();for(int j=0;j<arrays[i].length();j++){JSONObject r=arrays[i].getJSONObject(j);hashes.put(r.getString("id"),LocalCandidateBackgroundAdapter.sourceDigest(r));}versions.put(keys[i],hashes);}
  JSONObject out=new JSONObject().put("schema",SCHEMA).put("securities",securities).put("topics",topics).put("relations",relations).put("docs",documents).put("versions",versions).put("demand",new JSONObject().put("text",text).put("themeIds",demandIds)).put("themes",new JSONObject().put("schema","explicit-theme-memberships/v1").put("scope","complete-selected-securities").put("securityIds",ids).put("memberships",members).put("boundary",BOUNDARY)).put("boundary",BOUNDARY);
  need(out.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length<=2*1024*1024,"完整所选证券、主题和原文超过2MiB，未截断");active(c);return new JSONObject(out.toString());
 }
 static List<String> strings(JSONArray a)throws Exception{List<String> out=new ArrayList<>();for(int i=0;i<a.length();i++){need(a.get(i) instanceof String,"所选ID必须为文本");out.add(a.getString(i));}return out;}
 static JSONArray relationIds(JSONObject h)throws Exception{JSONArray a=new JSONArray(),r=h.getJSONArray("relations");for(int i=0;i<r.length();i++)a.put(r.getJSONObject(i).getString("id"));return a;}
 static void verify(JSONObject h,BooleanSupplier c)throws Exception{JSONObject next=select(h,h.getJSONArray("securities"),strings(h.getJSONObject("demand").getJSONArray("themeIds")),strings(relationIds(h)),h.getJSONObject("demand").getString("text"),c);need(LocalCandidateModel.canonical(next).equals(LocalCandidateModel.canonical(h)),"主题选择正文、版本或映射被改动");}
 static void confirm(JSONObject h,JSONObject current,BooleanSupplier c)throws Exception{verify(h,c);JSONObject next=select(current,h.getJSONArray("securities"),strings(h.getJSONObject("demand").getJSONArray("themeIds")),strings(relationIds(h)),h.getJSONObject("demand").getString("text"),c);need(LocalCandidateModel.canonical(next).equals(LocalCandidateModel.canonical(h)),"所选主题、成员或原文版本已变化；旧证据保留，请重新选择预览");}
 static void clocks(JSONObject h,Instant cut)throws Exception{for(String key:new String[]{"topics","relations","docs"}){JSONArray rows=h.getJSONArray(key);for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);if(r.has("updatedAt"))need(!Instant.parse(r.getString("updatedAt")).isAfter(cut),"所选资料保存时刻晚于观察时刻");}}}
 static String describe(JSONObject h)throws Exception{verify(h,null);StringBuilder s=new StringBuilder("明确主题背景 · 完整版本预览\n").append(BOUNDARY).append("\n需求：").append(h.getJSONObject("demand").getString("text")).append("\n已知：所选完整证券身份、主题ID、逐字资料引文及来源版本。\n未知：全市场归属、独立事实核验、发布时可获得性；缺失保存时间不改写为历史时点。\n");JSONArray ids=h.getJSONObject("themes").getJSONArray("securityIds"),members=h.getJSONObject("themes").getJSONArray("memberships");for(int i=0;i<ids.length();i++){int n=0;for(int j=0;j<members.length();j++)if(members.getJSONObject(j).getString("securityId").equals(ids.getString(i)))n++;s.append(ids.getString(i)).append(" · 明确所选成员记录 ").append(n).append("（仅此资料范围）\n");}JSONArray topics=h.getJSONArray("topics"),relations=h.getJSONArray("relations"),docs=h.getJSONArray("docs");for(int i=0;i<topics.length();i++){JSONObject r=topics.getJSONObject(i);s.append("\n需求主题：").append(r.optString("name")).append(" · ").append(r.getString("id")).append("\n保存时点：").append(r.optString("updatedAt","未知")).append("\n完整版本摘要：").append(h.getJSONObject("versions").getJSONObject("topics").getString(r.getString("id"))).append('\n');}for(int i=0;i<relations.length();i++){JSONObject r=relations.getJSONObject(i);s.append("\n所选成员来源：").append(r.getString("id")).append(" · ").append(r.getJSONObject("company").getString("instrumentId")).append(" · 主题 ").append(r.getString("topicId")).append("\n原记录核验状态：").append(r.optString("verification","unverified")).append("（不升级为事实）\n关系说明：").append(r.optString("claim")).append("\n逐字引文：").append(r.getString("quote")).append("\n身份引文：").append(r.getJSONObject("company").getString("identityQuote")).append('\n');}for(int i=0;i<docs.length();i++){JSONObject r=docs.getJSONObject(i);s.append("\n资料原文：").append(r.optString("title")).append(" · ").append(r.getString("id")).append("\n来源链接：").append(r.optString("sourceUrl","未知")).append("\n保存时点：").append(r.optString("updatedAt","未知")).append(" · 发布时可获得性：未证实\n完整版本摘要：").append(h.getJSONObject("versions").getJSONObject("docs").getString(r.getString("id"))).append('\n').append(r.getString("text")).append('\n');if(r.has("originalText"))s.append("保留的原始正文：\n").append(r.getString("originalText")).append('\n');}return s.append("\n以下保留完整字段供逐项复核：\n完整证券 / 主题 / 关系 / 原文与逐项版本摘要：\n").append(h.toString(2)).toString();}
}
